[
  {
    "title": "front-kick-foot-visibility",
    "claim": "In Images #13 and #22, no foot is discernible beyond Asmongold’s raised trouser cuff, while his planted foot is clearly visible.",
    "reason": "The kicking silhouette makes the striking surface difficult to identify; this alone does not establish a missing limb or an atlas defect.",
    "suggest": "Inspect the full-resolution pose and its sampled atlas crop, then correct the crop or use a pose that visibly exposes the kicking foot, depending on what that inspection establishes."
  },
  {
    "title": "technique-labels-hide-actions",
    "claim": "Image #3 labels the technique directions as back, forward, up, and down, whereas Image #6 explains those directions as reverse, punch, kick, and sweep.",
    "reason": "The in-fight reference repeats directions instead of providing the action meanings a new player needs.",
    "suggest": "Label the technique-side hints Reverse, Punch, Kick, and Sweep in their corresponding positions, preserving the existing input mapping."
  },
  {
    "title": "technique-list-continuation",
    "claim": "Image #6 ends partway through the Back Kick row, with additional reference content outside the visible frame and no explicit scroll instruction.",
    "reason": "Players cannot see the complete move reference in this view and may overlook its continuation.",
    "suggest": "Add an 18px-or-larger 'Scroll for more techniques' cue above the list; verify that the final technique is reachable before making any claim about broken scrolling."
  },
  {
    "title": "winning-threshold-copy",
    "claim": "Image #6 says 'First to 2 takes the round,' while Image #8 displays HasanAbi winning with 2½ points.",
    "reason": "These can agree when an award crosses the winning threshold, but the visible explanation leaves that possibility unstated.",
    "suggest": "Change the rule summary to 'Reach 2 points or more to win the round,' retaining the actual final score rather than treating this screenshot as evidence of a scoring bug."
  },
  {
    "title": "desktop-type-needs-measurement",
    "claim": "Image #9 shows fighter-name and STANCE/TECHNIQUE labels, but their computed CSS font sizes cannot be established from the supplied raster.",
    "reason": "These labels need to satisfy the required readability minimum, and estimating CSS pixels from this screenshot would not verify compliance.",
    "suggest": "Measure computed font sizes and check ancestor scaling at the original desktop viewport and 390×844, increasing only labels verified below 18 CSS px and adjusting layout rather than shrinking text."
  }
]
